/**
 * Edit one record with a form built from the entity schema: each field's label, type and enum
 * options come from `knowledge_entity_schema`, never from this file. Saving runs the one
 * automation tools.json grants; its handler checks the viewer's role and writes only the fields
 * it allows. Leaving a form with unsaved changes asks first.
 */
import { createRoot } from 'react-dom/client';
import { useState } from 'react';
import {
  SurfaceApp,
  SurfaceForm,
  parseAsString,
  toast,
  useConfirm,
  useMutation,
  useNavigation,
  useQuery,
  useQueryState,
  type SurfaceFormField,
  type SurfaceFormValues,
} from '@cynap/surface-sdk';

import './styles.css';

/** The org's entity type, and the fields this form edits. Replace both; the handler holds the same list. */
const ENTITY_TYPE = 'REPLACE_WITH_ENTITY_TYPE';
const EDITABLE_FIELDS = ['REPLACE_WITH_FIELD'];
/** Must match tools.json `automationIds` and `triggerActions`. */
const SAVE_AUTOMATION = 'record-form-save';
const SAVE_ACTION = 'save';
/** Where "Back" goes: the portal path of the list this form was opened from. */
const LIST_PATH = '/data';

type Row = Record<string, unknown>;
const isRecord = (value: unknown): value is Row => typeof value === 'object' && value !== null && !Array.isArray(value);
const text = (value: unknown) => (typeof value === 'string' ? value : '');

/** One schema field → one form field. Unknown types are a text input. */
function toFormField(field: Row): SurfaceFormField | null {
  const name = text(field.name);
  if (!EDITABLE_FIELDS.includes(name)) return null;
  const label = text(field.display_name) || name;
  const options = Array.isArray(field.enum_values) ? field.enum_values.filter((value): value is string => typeof value === 'string') : [];
  if (options.length > 0) return { kind: 'select', name, label, options: options.map((value) => ({ value, label: value })) };
  if (field.type === 'number' || field.type === 'integer') return { kind: 'number', name, label, integer: field.type === 'integer' };
  if (field.type === 'boolean') return { kind: 'checkbox', name, label };
  if (field.type === 'text') return { kind: 'textarea', name, label, maxLength: 4000 };
  return { kind: 'text', name, label, maxLength: 500 };
}

function readFields(payload: unknown): SurfaceFormField[] | null {
  if (!isRecord(payload) || !Array.isArray(payload.fields)) return null;
  return payload.fields.filter(isRecord).flatMap((field) => toFormField(field) ?? []);
}

/** `knowledge_query` by id returns `{entities: [entity], relations}`; fields may sit under `properties`. */
function readRecord(payload: unknown): SurfaceFormValues | null {
  const entity = isRecord(payload) && Array.isArray(payload.entities) ? payload.entities.find(isRecord) : undefined;
  if (entity === undefined) return null;
  const properties = isRecord(entity.properties) ? { ...entity, ...entity.properties } : entity;
  return Object.fromEntries(
    EDITABLE_FIELDS.map((name) => {
      const value = properties[name];
      return [name, typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean' ? value : null];
    })
  );
}

function RecordForm() {
  const [recordId] = useQueryState('id', parseAsString);
  const [dirty, setDirty] = useState(false);
  const confirm = useConfirm();
  const { navigate } = useNavigation();
  const schema = useQuery('knowledge_entity_schema', { entity_type: ENTITY_TYPE }, { parse: readFields });
  const record = useQuery('knowledge_query', { entity_id: recordId ?? '' }, { parse: readRecord, enabled: recordId !== null });
  const save = useMutation('automation_run_manual', { invalidates: ['knowledge_'] });

  async function onSave(values: SurfaceFormValues) {
    const verdict = await save.mutate({
      automation_id: SAVE_AUTOMATION,
      trigger_data: { action: SAVE_ACTION, record_id: recordId ?? '', values },
    });
    if (verdict === 'applied') {
      setDirty(false);
      toast('Saved.', { tone: 'success' });
    } else if (verdict === 'accepted') toast('Sent; the outcome is not confirmed yet.', { tone: 'info' });
    else toast('The record was not saved.', { tone: 'error' });
  }

  async function onBack() {
    if (dirty && !(await confirm({ title: 'Discard your changes?', body: 'This form has unsaved changes.', confirmLabel: 'Discard' }))) return;
    navigate(LIST_PATH);
  }

  if (recordId === null) return <p className="tpl-muted">No record selected.</p>;
  return (
    <main className="tpl-page">
      <button type="button" className="tpl-button" onClick={() => void onBack()}>
        Back
      </button>
      {schema.data && record.data ? (
        <div onInput={() => setDirty(true)} onChange={() => setDirty(true)}>
          <SurfaceForm
            key={recordId}
            fields={schema.data}
            initialValues={record.data}
            submitLabel="Save"
            disabled={save.state === 'pending'}
            onSubmit={(values) => void onSave(values)}
          />
        </div>
      ) : (
        <p className="tpl-muted">{schema.state === 'error' || record.state === 'error' ? 'This record could not be loaded.' : 'Loading…'}</p>
      )}
    </main>
  );
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'record-form', version: '1.0.0' }}>
      <RecordForm />
    </SurfaceApp>
  );
}

